(function () {
  const root = document.getElementById('clancy-assistant-root');
  if (!root) {
    return;
  }

  const helperName = root.dataset.helperName || 'Clancy';
  const fullUrl = root.dataset.fullUrl || '/clancy/';
  const defaultPrompt = root.dataset.initialPrompt || '';
  const contextPayload = readJsonScript('clancy-assistant-context', {});
  const csrfToken = getCookie('csrftoken');
  const panel = document.getElementById('clancy-assistant-panel');
  const input = document.getElementById('clancy-assistant-input');
  const form = document.getElementById('clancy-assistant-form');
  const messages = document.getElementById('clancy-assistant-messages');
  const status = document.getElementById('clancy-assistant-status');
  const fullLink = document.getElementById('clancy-assistant-full-link');
  const state = {
    threadId: null,
    isOpen: false,
    isSending: false,
    pollingTimer: null,
  };

  renderEmptyState();
  updateFullLink();

  document.addEventListener('click', (event) => {
    const openButton = event.target.closest('[data-clancy-open]');
    if (openButton) {
      if (openButton.tagName.toLowerCase() === 'button') {
        event.preventDefault();
      }
      const prompt = openButton.dataset.clancyPrompt || defaultPrompt;
      openAssistant(prompt);
      return;
    }

    if (event.target.closest('[data-clancy-close]')) {
      event.preventDefault();
      closeAssistant();
      return;
    }

    const proposalButton = event.target.closest('[data-clancy-proposal-action]');
    if (proposalButton) {
      event.preventDefault();
      void runProposalAction(proposalButton);
    }
  });

  form?.addEventListener('submit', (event) => {
    event.preventDefault();
    void sendMessage();
  });

  input?.addEventListener('input', () => {
    resizeInput();
    updateFullLink();
  });

  function readJsonScript(id, fallback) {
    const element = document.getElementById(id);
    if (!element) {
      return fallback;
    }
    try {
      return JSON.parse(element.textContent || '');
    } catch (_error) {
      return fallback;
    }
  }

  function getCookie(name) {
    const prefix = `${name}=`;
    return document.cookie
      .split(';')
      .map((cookie) => cookie.trim())
      .find((cookie) => cookie.startsWith(prefix))
      ?.slice(prefix.length) || '';
  }

  function openAssistant(prompt) {
    if (!panel) {
      return;
    }
    panel.hidden = false;
    state.isOpen = true;
    root.querySelectorAll('[data-clancy-open]').forEach((button) => {
      button.setAttribute('aria-expanded', 'true');
    });
    if (prompt && input && !input.value.trim()) {
      input.value = prompt;
      resizeInput();
      updateFullLink();
    }
    input?.focus();
  }

  function closeAssistant() {
    if (!panel) {
      return;
    }
    panel.hidden = true;
    state.isOpen = false;
    root.querySelectorAll('[data-clancy-open]').forEach((button) => {
      button.setAttribute('aria-expanded', 'false');
    });
  }

  async function apiRequest(path, options) {
    const settings = options || {};
    const headers = {
      Accept: 'application/json',
      ...(settings.headers || {}),
    };
    const method = settings.method || 'GET';
    let body = settings.body;

    if (settings.json !== undefined) {
      headers['Content-Type'] = 'application/json';
      body = JSON.stringify(settings.json);
    }

    if (method !== 'GET') {
      headers['X-CSRFToken'] = csrfToken;
    }

    const response = await fetch(path, {
      method,
      headers,
      body,
      credentials: 'same-origin',
    });
    const contentType = response.headers.get('content-type') || '';
    const payload = contentType.includes('application/json') ? await response.json() : await response.text();

    if (!response.ok) {
      const detail = typeof payload === 'object' && payload !== null
        ? payload.detail || payload.message || payload.error || Object.values(payload).flat().join(' ')
        : payload;
      throw new Error(detail || `Request failed with status ${response.status}`);
    }

    return payload;
  }

  async function ensureThread() {
    if (state.threadId) {
      return state.threadId;
    }
    const thread = await apiRequest('/api/family-agent/thread/');
    state.threadId = thread.id;
    return state.threadId;
  }

  async function sendMessage() {
    if (state.isSending || !input) {
      return;
    }
    const text = input.value.trim();
    if (!text) {
      return;
    }

    state.isSending = true;
    setStatus(`${helperName} is working...`);
    appendMessage({ role: 'user', text });
    input.value = '';
    resizeInput();
    updateFullLink();

    try {
      const threadId = await ensureThread();
      const response = await apiRequest('/api/family-agent/thread/messages/', {
        method: 'POST',
        json: {
          thread_id: threadId,
          text,
          context: contextPayload,
        },
      });
      state.threadId = response?.thread?.id || threadId;
      await loadMessages();
      schedulePolling();
    } catch (error) {
      appendMessage({ role: 'assistant', text: error.message || 'Something went wrong.' });
      setStatus('');
    } finally {
      state.isSending = false;
    }
  }

  async function loadMessages() {
    if (!state.threadId) {
      return;
    }
    const query = new URLSearchParams({ thread_id: state.threadId });
    const payload = await apiRequest(`/api/family-agent/thread/messages/?${query.toString()}`);
    const results = Array.isArray(payload?.results) ? payload.results.slice().reverse() : [];
    renderMessages(results);
    if (!hasPendingResponse(results)) {
      setStatus('');
      clearPolling();
    }
  }

  function schedulePolling() {
    clearPolling();
    state.pollingTimer = window.setInterval(() => {
      void loadMessages().catch((error) => {
        setStatus(error.message || 'Could not refresh the conversation.');
        clearPolling();
      });
    }, 1800);
  }

  function clearPolling() {
    if (state.pollingTimer) {
      window.clearInterval(state.pollingTimer);
      state.pollingTimer = null;
    }
  }

  async function runProposalAction(button) {
    const proposalId = button.dataset.clancyProposalId;
    const action = button.dataset.clancyProposalAction;
    if (!proposalId || !action) {
      return;
    }
    button.disabled = true;
    setStatus(action === 'approve' ? 'Approving...' : 'Rejecting...');
    try {
      await apiRequest(`/api/family-agent/proposals/${proposalId}/${action}/`, {
        method: 'POST',
        json: {},
      });
      await loadMessages();
      setStatus('');
    } catch (error) {
      button.disabled = false;
      setStatus(error.message || 'Could not update the proposal.');
    }
  }

  function renderEmptyState() {
    if (!messages) {
      return;
    }
    messages.replaceChildren();
    const empty = document.createElement('p');
    empty.className = 'clancy-assistant-empty';
    empty.textContent = `Ask ${helperName} for quick help, or open the full conversation when you need more room.`;
    messages.appendChild(empty);
  }

  function renderMessages(items) {
    if (!messages) {
      return;
    }
    messages.replaceChildren();
    if (!items.length) {
      renderEmptyState();
      return;
    }
    items.slice(-8).forEach((message) => appendMessage(message));
    messages.scrollTop = messages.scrollHeight;
  }

  function appendMessage(message) {
    if (!messages) {
      return;
    }
    const empty = messages.querySelector('.clancy-assistant-empty');
    empty?.remove();
    const wrapper = document.createElement('div');
    wrapper.className = `clancy-assistant-message ${message.role || 'assistant'}`;
    const bubble = document.createElement('div');
    bubble.className = 'clancy-assistant-bubble';
    bubble.textContent = message.text || '';
    renderProposalCards(bubble, message.proposals || []);
    wrapper.appendChild(bubble);
    messages.appendChild(wrapper);
    messages.scrollTop = messages.scrollHeight;
  }

  function renderProposalCards(container, proposals) {
    proposals.forEach((proposal) => {
      const card = document.createElement('div');
      card.className = 'clancy-assistant-card';
      const title = document.createElement('p');
      title.className = 'clancy-assistant-card-title';
      title.textContent = proposal.summary || 'Suggested update';
      const preview = document.createElement('p');
      preview.textContent = proposal.preview_text || proposal.status || '';
      card.append(title, preview);
      if (proposal.status === 'pending_approval') {
        const actions = document.createElement('div');
        actions.className = 'clancy-assistant-card-actions';
        actions.append(
          buildProposalButton(proposal.id, 'approve', 'Approve'),
          buildProposalButton(proposal.id, 'reject', 'Reject')
        );
        card.appendChild(actions);
      }
      container.appendChild(card);
    });
  }

  function buildProposalButton(id, action, label) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = action === 'approve' ? 'btn btn-primary btn-sm' : 'btn btn-outline-secondary btn-sm';
    button.dataset.clancyProposalId = id;
    button.dataset.clancyProposalAction = action;
    button.textContent = label;
    return button;
  }

  function hasPendingResponse(items) {
    return items.some((message) => {
      const runStatus = message.run_status || message.status;
      return runStatus && !['COMPLETED', 'FAILED'].includes(String(runStatus).toUpperCase());
    });
  }

  function setStatus(value) {
    if (status) {
      status.textContent = value || '';
    }
  }

  function resizeInput() {
    if (!input) {
      return;
    }
    input.style.height = 'auto';
    input.style.height = `${Math.min(input.scrollHeight, 144)}px`;
  }

  function updateFullLink() {
    if (!fullLink) {
      return;
    }
    const url = new URL(fullUrl, window.location.origin);
    Object.entries(contextPayload || {}).forEach(([key, value]) => {
      if (value !== null && value !== undefined && typeof value !== 'object') {
        url.searchParams.set(key, String(value));
      }
    });
    const prompt = input?.value.trim() || defaultPrompt;
    if (prompt) {
      url.searchParams.set('prompt', prompt);
    }
    fullLink.href = `${url.pathname}${url.search}`;
  }
})();

