596	                                                <span class="badge badge-rsvp-{{ participant.rsvp_status|lower }}">
597	                                                    {{ participant.get_rsvp_status_display }}
598	                                                </span>
599	                                            {% endif %}
600	                                        {% endfor %}
601	                                    </div>
602	                                    <div class="mt-2">
603	                                        <a href="{% url 'event_detail' event.id %}" class="btn btn-sm btn-outline-primary">View Details</a>
604	
605	                                        {% if event.creator == request.user %}
606	                                            <a href="{% url 'event_edit' event.id %}" class="btn btn-sm btn-outline-secondary">Edit</a>
607	                                        {% endif %}
608	                                    </div>
609	                                </div>
610	                                {% endfor %}
611	                            {% else %}
612	                                <div class="no-events">
613	                                    <i class="bi bi-calendar-x"></i>
614	                                    <h4>No upcoming events</h4>
615	                                    <p>Create a new event to get started.</p>
616	                                    <a href="{% url 'event_create' %}" class="btn btn-primary">Create Event</a>
617	                                </div>
618	                            {% endif %}
619	                        </div>
620	                    </div>
621	
622	                    <div class="card">
623	                        <div class="card-header d-flex justify-content-between align-items-center">
624	                            <h4>Past Events</h4>
625	                            <button class="btn btn-sm btn-link" type="button" data-bs-toggle="collapse" data-bs-target="#pastEventsCollapse" aria-expanded="false" aria-controls="pastEventsCollapse">
626	                                <i class="bi bi-chevron-down"></i>
627	                            </button>
628	                        </div>
629	                        <div class="collapse card-body" id="pastEventsCollapse">
630	                            {% if past_events %}
631	                                {% for event in past_events %}
632	                                <div class="event-card p-3 {% if event.visibility == 'PERSONAL' %}personal{% elif event.visibility == 'PRIVATE' %}private{% endif %}" style="border-left-color: {{ event.display_color|default:'var(--primary)' }};">
633	                                    <div class="event-time">
634	                                        {% if event.is_all_day %}
635	                                            {{ event.start_time|date:"l, F j, Y" }} — All Day
636	                                        {% elif event.start_time.date == event.end_time.date %}
637	                                            {{ event.start_time|date:"l, F j, Y" }} from {{ event.start_time|date:"g:i A" }} to {{ event.end_time|date:"g:i A" }}
638	                                        {% else %}
639	                                            {{ event.start_time|date:"l, F j, Y g:i A" }} to {{ event.end_time|date:"l, F j, Y g:i A" }}
640	                                        {% endif %}
641	                                    </div>
642	                                    <div class="event-title">
643	                                        {% with calendar_info=event_calendar_info|get_item:event.id child_info=event_child_info|get_item:event.id %}
644	                                        {% if calendar_info and calendar_info.type == 'SPORTS' %}
645	                                            {% sport_icon_class calendar_info.sports_subcategory as icon_cls %}
646	                                            <i class="event-color-marker {{ icon_cls }}" style="color: {{ event.display_color|default:'var(--primary)' }};" title="{{ calendar_info.sports_subcategory }}"></i>
647	                                        {% else %}
648	                                            <span class="event-color-dot" style="background-color: {{ event.display_color|default:'var(--primary)' }};"></span>
649	                                        {% endif %}
650	
651	                                        {% if calendar_info and calendar_info.associated_users %}
652	                                            {% with assoc_user=calendar_info.associated_users.0 %}
653	                                                <span class="event-owner" title="{{ assoc_user.name }}">
654	                                                    {% if assoc_user.avatar_url %}
655	                                                        <img src="{{ assoc_user.avatar_url }}" alt="{{ assoc_user.name }}" class="event-owner-avatar">
656	                                                    {% elif assoc_user.initials %}
657	                                                        <span class="event-owner-initials" style="background-color: {{ event.display_color|default:'var(--primary)' }};">
658	                                                            {{ assoc_user.initials }}
659	                                                        </span>
660	                                                    {% else %}
661	                                                        <span class="event-owner-initials" style="background-color: {{ event.display_color|default:'var(--primary)' }};">?</span>
662	                                                    {% endif %}
663	                                                    <span class="event-owner-name">{{ assoc_user.short_name|default:assoc_user.name }}</span>
664	                                                </span>
665	                                            {% endwith %}
666	                                        {% elif child_info %}
667	                                            <a href="{% url 'event_detail' event.id %}" class="child-event-display me-2" title="{{ event.title }}">
668	                                                <img src="{{ child_info.picture_url }}" alt="{{ child_info.name }}" class="child-event-img">
669	                                                <span class="child-event-name">{{ child_info.name }}</span>
670	                                            </a>
671	                                        {% endif %}
672	                                        <a href="{% url 'event_detail' event.id %}">{{ event.title }}</a>
673	                                        {% endwith %} {# End calendar_info with #}
674	                                    </div>
675	                                    {% if event.location %}
676	                                        <div class="event-location">
677	                                            <i class="bi bi-geo-alt"></i> {{ event.location }}
678	                                        </div>
679	                                    {% endif %}
680	                                    <div class="event-meta">
681	                                        <span class="badge {% if event.visibility == 'PUBLIC' %}bg-primary{% elif event.visibility == 'PRIVATE' %}bg-warning{% else %}bg-success{% endif %}">
682	                                            {{ event.get_visibility_display }}
683	                                        </span>
684	
685	                                        {% if event.family_group %}
686	                                            <span class="badge bg-info">{{ event.family_group.name }}</span>
687	                                        {% endif %}
688	
689	                                        {% for participant in event.participants.all %}
690	                                            {% if participant.user == request.user %}
691	                                                <span class="badge badge-rsvp-{{ participant.rsvp_status|lower }}">
692	                                                    {{ participant.get_rsvp_status_display }}
693	                                                </span>
694	                                            {% endif %}
695	                                        {% endfor %}
696	                                    </div>
697	                                    <div class="mt-2">
698	                                        <a href="{% url 'event_detail' event.id %}" class="btn btn-sm btn-outline-primary">View Details</a>
699	                                    </div>
700	                                </div>
701	                                {% endfor %}
702	                            {% else %}
703	                                <p class="text-muted">No past events.</p>
704	                            {% endif %}
705	                        </div>
706	                    </div>
707	                </div>
708	
709	                <div class="col-lg-4">
710	                    <div class="card mb-4">
711	                        <div class="card-header">
712	                            <h5>Quick Actions</h5>
713	                        </div>
714	                        <div class="card-body">
715	                            <div class="d-grid gap-2">
716	                                <a href="{% url 'event_create' %}" class="btn btn-primary text-truncate">
717	                                    <i class="bi bi-plus-circle me-1"></i>Create New Event
718	                                </a>
719	                                {% if family_features.clancy_available %}
720	                                <button type="button"
721	                                        class="btn btn-outline-primary text-truncate"
722	                                        data-clancy-open
723	                                        data-clancy-prompt="Help me add an event to our family calendar.">
724	                                    <i class="bi bi-stars me-1"></i>Quick Ask {{ family_features.helper_agent_name|default:"Clancy" }}
725	                                </button>
726	                                {% endif %}
727	                                <a href="{% url 'calendars:quick_connect' %}" class="btn btn-outline-success text-truncate">
728	                                    <i class="bi bi-calendar-plus me-1"></i>Quick Add Calendar
729	                                </a>
730	                                <a href="{% url 'event_bulk_select' %}" class="btn btn-outline-primary text-truncate" title="Select and edit multiple existing events">
731	                                    <i class="bi bi-pencil-square me-1"></i>Bulk Edit Existing Events
732	                                </a>
733	                                <a href="{% url 'csv_import' %}" class="btn btn-outline-info text-truncate" title="Import events from CSV file">
734	                                    <i class="bi bi-file-earmark-arrow-up me-1"></i>Import Events from CSV
735	                                </a>
736	                                <!-- <a href="{% url 'calendars:calendar' %}" class="btn btn-outline-primary">Calendar View</a>
737	                                <a href="{% url 'calendars:week_view' %}" class="btn btn-outline-primary">Week View</a>
738	                                <a href="{% url 'calendars:day_view_with_date' now.year now.month now.day %}" class="btn btn-outline-primary">Today's Events</a> -->
739	                            </div>
740	                        </div>
741	                    </div>
742	
743	                    <div class="col-md-12">
744	                      <div class="card">
745	                          <div class="card-header">
746	                              <h5>My Calendars</h5>
747	                          </div>
748	                          <div class="card-body">
749	                              {% if external_calendars or internal_calendars %}
750	                                  <ul class="list-group">
751	                                      {% for calendar in external_calendars %}
752	                                      <li class="list-group-item d-flex justify-content-between align-items-center">
753	                                          <div>
754	                                              {% if calendar.type == 'SPORTS' %}
755	                                                  {% sport_icon_class calendar.sports_subcategory as icon_cls %}
756	                                                  <i class="{{ icon_cls }}" title="{{ calendar.sports_subcategory }}"></i>
757	                                              {% endif %}
758	                                              {{ calendar.account_name }} ({{ calendar.get_provider_display }})
759	                                          </div>
760	                                          <span class="badge {% if calendar.is_active %}bg-success{% else %}bg-secondary{% endif %} rounded-pill">
761	                                              {% if calendar.is_active %}Active{% else %}Inactive{% endif %}
762	                                          </span>
763	                                      </li>
764	                                      {% endfor %}
765	
766	                                      {% for calendar in internal_calendars %}
767	                                      <li class="list-group-item d-flex justify-content-between align-items-center">
768	                                          <div>
769	                                              {% if calendar.type == 'SPORTS' %}
770	                                                  {% sport_icon_class calendar.sports_subcategory as icon_cls %}
771	                                                  <i class="{{ icon_cls }}" title="{{ calendar.sports_subcategory }}"></i>
772	                                              {% endif %}
773	                                              {{ calendar.name }}
774	                                          </div>
775	                                          <span class="badge {% if calendar.is_active %}bg-success{% else %}bg-secondary{% endif %} rounded-pill">
776	                                              {% if calendar.is_active %}Active{% else %}Inactive{% endif %}
777	                                          </span>
778	                                      </li>
779	                                      {% endfor %}
780	                                  </ul>
781	                                  <div class="mt-3">
782	                                      <a href="{% url 'calendars:calendar_list' %}" class="btn btn-outline-primary">Manage Calendars</a>
783	                                  </div>
784	                              {% else %}
785	                                  <p>No calendars configured.</p>
786	                                  <a href="{% url 'calendars:calendar_list' %}" class="btn btn-primary">Add Calendar</a>
787	                              {% endif %}
788	                          </div>
789	                      </div>
790	                  </div>
791	                </div>
792	            </div>
793	        </div>
794	    </div>
795	</div>
796	{% endblock %}
797	
798	{% block extra_js %}
799	<script>
800	function initializeEventFilters() {
801	    // Get user identifier for localStorage namespacing
802	    const userId = '{{ request.user.id|default:"anonymous" }}';
803	
804	    // Date range custom fields toggle
805	    const dateRangeSelect = document.getElementById('date_range');
806	    const customDateRangeFields = document.querySelectorAll('.custom-date-range');
807	
808	    function toggleCustomDateRange() {
809	        if (!dateRangeSelect) return;
810	        const showCustom = dateRangeSelect.value === 'CUSTOM';
811	        customDateRangeFields.forEach(field => {
812	            field.style.display = showCustom ? 'block' : 'none';
813	        });
814	    }
815	
816	    if (dateRangeSelect) {
817	        dateRangeSelect.addEventListener('change', toggleCustomDateRange);
818	        toggleCustomDateRange(); // Initial state
819	    }
820	
821	    // Mobile filter sidebar toggle
822	    const filterToggleMobile = document.getElementById('filterToggleMobile');
823	    const filterSidebar = document.getElementById('filterSidebar');
824	    const filterOverlay = document.getElementById('filterOverlay');
825	
826	    if (filterToggleMobile && filterSidebar && filterOverlay) {
827	        filterToggleMobile.addEventListener('click', function() {
828	            filterSidebar.classList.toggle('active');
829	            filterOverlay.classList.toggle('active');
830	        });
831	
832	        filterOverlay.addEventListener('click', function() {
833	            filterSidebar.classList.remove('active');
834	            filterOverlay.classList.remove('active');
835	        });
836	    }
837	
838	    // Count active filters and update badge
839	    function updateActiveFilterCount() {
840	        let activeCount = 0;
841	        const searchInput = document.getElementById('q');
842	        const familySelect = document.getElementById('family');
843	        const visibilitySelect = document.getElementById('visibility');
844	        const dateRangeSelect = document.getElementById('date_range');
845	
846	        if (searchInput && searchInput.value) activeCount++;
847	        if (familySelect && familySelect.value) activeCount++;
848	        if (visibilitySelect && visibilitySelect.value) activeCount++;
849	        if (dateRangeSelect && dateRangeSelect.value) activeCount++;
850	
851	        const badge = document.getElementById('activeFiltersCount');
852	        if (badge) {
853	            if (activeCount > 0) {
854	                badge.textContent = activeCount + ' Active';
855	                badge.style.display = 'inline-block';
856	            } else {
857	                badge.style.display = 'none';
858	            }
859	        }
860	
861	        // Update mobile button badge
862	        if (filterToggleMobile && activeCount > 0) {
863	            filterToggleMobile.innerHTML = '<i class="bi bi-funnel-fill"></i>';
864	            filterToggleMobile.style.background = 'var(--warning)';
865	        } else if (filterToggleMobile) {
866	            filterToggleMobile.innerHTML = '<i class="bi bi-funnel"></i>';
867	            filterToggleMobile.style.background = 'var(--primary)';
868	        }
869	    }
870	
871	    // Update count on page load
872	    updateActiveFilterCount();
873	
874	    // Filter persistence with localStorage (namespaced per user)
875	    const FILTER_STORAGE_KEY = `eventListFilters_${userId}`;
876	
877	    // Save filter state to localStorage
878	    function saveFilterState() {
879	        try {
880	            const searchInput = document.getElementById('q');
881	            const familySelect = document.getElementById('family');
882	            const visibilitySelect = document.getElementById('visibility');
883	            const dateRangeSelect = document.getElementById('date_range');
884	            const monthSelect = document.getElementById('month');
885	            const yearSelect = document.getElementById('year');
886	
887	            const filterState = {
888	                search: searchInput ? searchInput.value : '',
889	                family: familySelect ? familySelect.value : '',
890	                visibility: visibilitySelect ? visibilitySelect.value : '',
891	                dateRange: dateRangeSelect ? dateRangeSelect.value : '',
892	                month: monthSelect ? monthSelect.value : '',
893	                year: yearSelect ? yearSelect.value : '',
894	                timestamp: Date.now()
895	            };
896	            localStorage.setItem(FILTER_STORAGE_KEY, JSON.stringify(filterState));
897	        } catch (e) {
898	            console.error('Error saving filter state:', e);
899	        }
900	    }
901	
902	    // Load filter state from localStorage (only if no filters in URL)
903	    function loadFilterState() {
904	        try {
905	            // Check if there are any filters in the URL
906	            const urlParams = new URLSearchParams(window.location.search);
907	            const hasUrlFilters = urlParams.get('q') || urlParams.get('family') ||
908	                                 urlParams.get('visibility') || urlParams.get('date_range');
909	
910	            if (!hasUrlFilters) {
911	                const savedState = localStorage.getItem(FILTER_STORAGE_KEY);
912	                if (savedState) {
913	                    const filterState = JSON.parse(savedState);
914	
915	                    // Only restore if saved within last 24 hours
916	                    const dayInMs = 24 * 60 * 60 * 1000;
917	                    if (Date.now() - filterState.timestamp < dayInMs) {
918	                        // Ask user if they want to restore filters
919	                        const filterSummary = [];
920	                        if (filterState.search) filterSummary.push('Search: ' + filterState.search);
921	                        if (filterState.family) filterSummary.push('Family filter');
922	                        if (filterState.visibility) filterSummary.push('Visibility filter');
923	                        if (filterState.dateRange) filterSummary.push('Date filter');
924	
925	                        if (filterSummary.length > 0) {
926	                            // Create a subtle notification instead of confirm dialog
927	                            const restoreBar = document.createElement('div');
928	                            restoreBar.className = 'alert alert-info alert-dismissible fade show mb-3';
929	                            restoreBar.innerHTML = `
930	                                <i class="bi bi-info-circle me-2"></i>
931	                                <strong>Previous filters detected:</strong> ${filterSummary.join(', ')}
932	                                <button type="button" class="btn btn-sm btn-primary ms-3" id="restoreFilters">
933	                                    <i class="bi bi-arrow-clockwise me-1"></i>Restore
934	                                </button>
935	                                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
936	                            `;
937	
938	                            const mainContent = document.querySelector('.events-main-content');
939	                            if (mainContent) {
940	                                mainContent.insertBefore(restoreBar, mainContent.firstChild);
941	
942	                                document.getElementById('restoreFilters')?.addEventListener('click', function() {
943	                                    // Restore filter values with null checks
944	                                    const searchInput = document.getElementById('q');
945	                                    const familySelect = document.getElementById('family');
946	                                    const visibilitySelect = document.getElementById('visibility');
947	                                    const dateRangeSelect = document.getElementById('date_range');
948	                                    const monthSelect = document.getElementById('month');
949	                                    const yearSelect = document.getElementById('year');
950	                                    const filterForm = document.getElementById('filterForm');
951	
952	                                    if (filterState.search && searchInput) searchInput.value = filterState.search;
953	                                    if (filterState.family && familySelect) familySelect.value = filterState.family;
954	                                    if (filterState.visibility && visibilitySelect) visibilitySelect.value = filterState.visibility;
955	                                    if (filterState.dateRange && dateRangeSelect) {
956	                                        dateRangeSelect.value = filterState.dateRange;
957	                                        toggleCustomDateRange();
958	                                    }
959	                                    if (filterState.month && monthSelect) monthSelect.value = filterState.month;
960	                                    if (filterState.year && yearSelect) yearSelect.value = filterState.year;
961	
962	                                    // Submit the form if it exists
963	                                    if (filterForm) {
964	                                        filterForm.submit();
965	                                    }
966	                                });
967	                            }
968	                        }
969	                    }
970	                }
971	            }
972	        } catch (e) {
973	            console.error('Error loading filter state:', e);
974	        }
975	    }
976	
977	    // Save filters when they change
978	    const filterInputs = document.querySelectorAll('#filterForm select, #filterForm input');
979	    filterInputs.forEach(input => {
980	        input.addEventListener('change', saveFilterState);
981	    });
982	
983	    // Clear saved filters when Clear All is clicked
984	    const clearButton = document.querySelector('.clear-filters-btn');
985	    if (clearButton) {
986	        clearButton.addEventListener('click', function() {
987	            localStorage.removeItem(FILTER_STORAGE_KEY);
988	        });
989	    }
990	
991	    // Load filter state on page load
992	    loadFilterState();
993	
994	    // Auto-submit filters on change (optional - commented out for now)
995	    // const filterForm = document.getElementById('filterForm');
996	    // filterInputs.forEach(input => {
997	    //     input.addEventListener('change', function() {
998	    //         saveFilterState();
999	    //         filterForm.submit();
1000	    //     });
1001	    // });
1002	}
1003	
1004	if (document.readyState === 'loading') {
1005	    document.addEventListener('DOMContentLoaded', initializeEventFilters);
1006	} else {
1007	    initializeEventFilters();
1008	}
1009	</script>
1010	{% endblock %}
