{% extends "base.html" %}
{% load static event_extras calendar_extras %} {# Load calendar_extras #}

{% block title %}Events{% endblock %}

{% block extra_css %}
<style>
    /* Sidebar Layout */
    .events-container {
        display: flex;
        gap: var(--space-4);
        margin-top: var(--space-4);
    }

    .filter-sidebar {
        flex: 0 0 280px;
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: var(--space-4);
        height: fit-content;
        position: sticky;
        top: 20px;
        border-top: 3px solid var(--section-events, #0080FF);
    }

    .events-main-content {
        flex: 1;
        min-width: 0;
    }

    .filter-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: var(--space-4);
        padding-bottom: var(--space-3);
        border-bottom: 1px solid var(--gray-200);
    }

    .filter-header h5 {
        margin: 0;
        font-size: var(--font-size-lg);
        font-weight: 600;
        color: var(--gray-900);
    }

    .active-filters-badge {
        background: var(--warning);
        color: var(--white);
        padding: 2px 8px;
        border-radius: var(--radius-full);
        font-size: var(--font-size-sm);
        font-weight: 600;
    }

    .filter-group {
        margin-bottom: var(--space-4);
    }

    .filter-group label {
        display: block;
        margin-bottom: var(--space-2);
        font-weight: 500;
        color: var(--gray-700);
        font-size: var(--font-size-sm);
    }

    .filter-actions {
        display: flex;
        gap: var(--space-2);
        margin-top: var(--space-4);
        padding-top: var(--space-4);
        border-top: 1px solid var(--gray-200);
    }

    .clear-filters-btn {
        flex: 1;
    }

    /* Mobile Sidebar */
    .filter-toggle-mobile {
        display: none;
        position: fixed;
        bottom: 20px;
        right: 20px;
        width: 56px;
        height: 56px;
        border-radius: var(--radius-full);
        background: var(--primary);
        color: var(--white);
        box-shadow: var(--shadow-lg);
        z-index: 1000;
        border: none;
        font-size: 1.25rem;
    }

    @media (max-width: 768px) {
        .events-container {
            flex-direction: column;
        }

        .filter-sidebar {
            position: fixed;
            top: 0;
            left: -100%;
            width: 80%;
            max-width: 320px;
            height: 100vh;
            z-index: 1050;
            transition: left 0.3s ease;
            overflow-y: auto;
        }

        .filter-sidebar.active {
            left: 0;
        }

        .filter-overlay {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.5);
            z-index: 1040;
        }

        .filter-overlay.active {
            display: block;
        }

        .filter-toggle-mobile {
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .events-main-content {
            width: 100%;
        }
    }

    /* Event List Styles */
    .event-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: var(--space-6);
    }

    .event-filters {
        display: flex;
        gap: var(--space-3);
        align-items: center;
        flex-wrap: wrap;
    }

    .event-card {
        background-color: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: var(--space-4);
        margin-bottom: var(--space-4);
        border-left: 4px solid var(--primary);
        transition: all var(--transition-base);
    }

    .event-card:hover {
        box-shadow: var(--shadow-md);
        transform: translateY(-2px);
    }

    .event-card.personal {
        border-left-color: var(--success);
    }

    .event-card.private {
        border-left-color: var(--warning);
    }

    .event-header-content {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        margin-bottom: var(--space-2);
    }

    .event-title {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: var(--space-2);
        font-size: var(--font-size-lg);
        font-weight: 600;
        color: var(--gray-900);
        margin-bottom: var(--space-1);
        text-decoration: none;
    }

    .event-title:hover {
        color: var(--primary);
    }

    .event-color-dot {
        width: 10px;
        height: 10px;
        border-radius: var(--radius-full);
        flex-shrink: 0;
    }

    .event-color-marker {
        font-size: 1.25rem;
        line-height: 1;
        flex-shrink: 0;
    }

    .event-owner {
        display: inline-flex;
        align-items: center;
        gap: var(--space-2);
        padding: 2px 8px;
        border-radius: var(--radius-full);
        background-color: var(--gray-100);
        font-size: var(--font-size-sm);
        color: var(--gray-700);
    }

    .event-owner-avatar {
        width: 22px;
        height: 22px;
        border-radius: var(--radius-full);
        object-fit: cover;
        box-shadow: var(--shadow-sm);
    }

    .event-owner-initials {
        width: 22px;
        height: 22px;
        border-radius: var(--radius-full);
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 0.7rem;
        font-weight: 600;
        color: var(--white);
    }

    .event-owner-name {
        font-weight: 600;
    }

    .event-time {
        display: flex;
        align-items: center;
        gap: var(--space-2);
        color: var(--gray-600);
        font-size: var(--font-size-sm);
        margin-bottom: var(--space-2);
    }

    .event-location {
        display: flex;
        align-items: center;
        gap: var(--space-2);
        color: var(--gray-600);
        font-size: var(--font-size-sm);
        margin-bottom: var(--space-2);
    }

    .event-meta {
        display: flex;
        gap: var(--space-4);
        flex-wrap: wrap;
        font-size: var(--font-size-sm);
        color: var(--gray-500);
    }

    .event-meta-item {
        display: flex;
        align-items: center;
        gap: var(--space-1);
    }

    .event-actions {
        display: flex;
        gap: var(--space-2);
    }

    /* Child Event Display */
    .child-event-display {
        position: relative;
        display: inline-block;
        margin-right: var(--space-1);
    }

    .child-event-img {
        width: 2rem;
        height: 2rem;
        border-radius: var(--radius-full);
        object-fit: cover;
        border: 2px solid var(--white);
        box-shadow: var(--shadow-sm);
    }

    .child-event-name {
        position: absolute;
        bottom: -4px;
        left: 50%;
        transform: translateX(-50%);
        background-color: var(--gray-900);
        color: var(--white);
        font-size: 0.625rem;
        padding: 1px 4px;
        border-radius: var(--radius-sm);
        white-space: nowrap;
        opacity: 0;
        transition: opacity var(--transition-fast);
    }

    .child-event-display:hover .child-event-name {
        opacity: 1;
    }

    /* RSVP Badges */
    .badge-rsvp-yes {
        background-color: var(--success-light);
        color: var(--success);
    }

    .badge-rsvp-no {
        background-color: var(--danger-light);
        color: var(--danger);
    }

    .badge-rsvp-maybe {
        background-color: var(--warning-light);
        color: var(--warning);
    }
    .badge-rsvp-pending {
        background-color: #6c757d;
    }
    .no-events {
        text-align: center;
        padding: 3rem 2rem;
        color: var(--gray-500);
    }
    .no-events > i {
        font-size: 3rem;
        opacity: 0.3;
        margin-bottom: 1rem;
    }
    .no-events h4 {
        color: var(--gray-600);
        font-weight: 500;
        margin-bottom: 0.5rem;
    }
    .no-events p {
        margin-bottom: 1.5rem;
    }

    /* Quick Actions Card Fix - only apply to buttons with text-truncate class */
    .card-body .d-grid .btn.text-truncate {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        padding: 0.5rem 1rem;
    }

    .card-body .d-grid .btn i {
        flex-shrink: 0;
    }

    /* Ensure cards don't overflow on smaller screens */
    @media (max-width: 1200px) {
        .col-lg-4 .card {
            overflow: hidden;
        }

        .card-body .d-grid .btn.text-truncate {
            font-size: 0.9rem;
            padding: 0.45rem 0.75rem;
        }
    }
</style>
{% endblock %}

{% block content %}
<div class="container">
    <div class="event-list-header d-flex justify-content-between align-items-center">
        <h1><i class="bi bi-calendar-event me-2" style="color: var(--section-events, #0080FF);"></i>Events</h1>
        <div class="d-flex gap-2">
            {% if family_features.clancy_available %}
            <a href="{% url 'family_agent:planner' %}?source_screen=event_list&family_id={{ family_features.family_id }}&prompt=Help%20me%20add%20an%20event%20to%20our%20family%20calendar."
               class="btn btn-outline-primary">
                <i class="bi bi-stars me-2"></i>Ask {{ family_features.helper_agent_name|default:"Clancy" }}
            </a>
            {% endif %}
            <a href="{% url 'events:event_map' %}" class="btn btn-outline-secondary">
                <i class="bi bi-geo-alt me-2"></i>Map View
            </a>
            <a href="{% url 'calendars:calendar' %}" class="btn btn-outline-secondary">
                <i class="bi bi-calendar3 me-2"></i>Calendar View
            </a>
        </div>
    </div>

    <div class="events-container">
        <!-- Filter Sidebar -->
        <aside class="filter-sidebar" id="filterSidebar">
            <div class="filter-header">
                <h5><i class="bi bi-funnel me-2"></i>Filters</h5>
                {% if selected_family or selected_visibility or selected_date_range or search_query %}
                    <span class="active-filters-badge" id="activeFiltersCount">Active</span>
                {% endif %}
            </div>

            <form method="get" action="{% url 'event_list' %}" id="filterForm">
                <div class="filter-content">
                    <!-- Search Filter -->
                    <div class="filter-group">
                        <label for="q">Search</label>
                        <input type="text" class="form-control" id="q" name="q"
                               placeholder="Title, location..."
                               value="{{ search_query|default:'' }}">
                    </div>

                    <!-- Family Filter -->
                    <div class="filter-group">
                        <label for="family">Family</label>
                        <select class="form-select" id="family" name="family">
                            <option value="">All Families</option>
                            {% for family in family_groups %}
                                <option value="{{ family.id }}" {% if selected_family.id == family.id %}selected{% endif %}>{{ family.name }}</option>
                            {% endfor %}
                        </select>
                    </div>

                    <!-- Visibility Filter -->
                    <div class="filter-group">
                        <label for="visibility">Visibility</label>
                        <select class="form-select" id="visibility" name="visibility">
                            <option value="">All Visibilities</option>
                            {% for value, label in visibility_choices %}
                                <option value="{{ value }}" {% if selected_visibility == value %}selected{% endif %}>{{ label }}</option>
                            {% endfor %}
                        </select>
                    </div>


                    <!-- Date Range Filter -->
                    <div class="filter-group">
                        <label for="date_range">Date Range</label>
                        <select class="form-select" id="date_range" name="date_range">
                            <option value="">All Dates</option>
                            <option value="CURRENT_MONTH" {% if selected_date_range == 'CURRENT_MONTH' %}selected{% endif %}>Current Month</option>
                            <option value="NEXT_MONTH" {% if selected_date_range == 'NEXT_MONTH' %}selected{% endif %}>Next Month</option>
                            <option value="CUSTOM" {% if selected_date_range == 'CUSTOM' %}selected{% endif %}>Custom Month/Year</option>
                            <option value="WEEK" {% if selected_date_range == 'WEEK' %}selected{% endif %}>Next 7 Days</option>
                            <option value="MONTH" {% if selected_date_range == 'MONTH' %}selected{% endif %}>Next 30 Days</option>
                            <option value="YEAR" {% if selected_date_range == 'YEAR' %}selected{% endif %}>Next 365 Days</option>
                        </select>
                    </div>

                    <!-- Custom Month/Year Selection (initially hidden) -->
                    <div class="filter-group custom-date-range" style="display: none;">
                        <label for="month">Month</label>
                        <select class="form-select" id="month" name="month">
                            {% for month_num, month_name in month_choices %}
                                <option value="{{ month_num }}" {% if selected_month == month_num %}selected{% endif %}>{{ month_name }}</option>
                            {% endfor %}
                        </select>
                    </div>

                    <div class="filter-group custom-date-range" style="display: none;">
                        <label for="year">Year</label>
                        <select class="form-select" id="year" name="year">
                            {% for year in year_choices %}
                                <option value="{{ year }}" {% if selected_year == year %}selected{% endif %}>{{ year }}</option>
                            {% endfor %}
                        </select>
                    </div>


                    <!-- Filter Actions -->
                    <div class="filter-actions">
                        <button type="submit" class="btn btn-primary btn-sm">
                            <i class="bi bi-check2"></i> Apply
                        </button>
                        <a href="{% url 'event_list' %}" class="btn btn-outline-secondary btn-sm clear-filters-btn">
                            <i class="bi bi-x"></i> Clear All
                        </a>
                    </div>
                </div>
            </form>

            <!-- Active Filters Display -->
            {% if selected_family or selected_visibility or selected_date_range or search_query %}
            <div class="mt-3 pt-3 border-top">
                <small class="text-muted d-block mb-2">Active Filters:</small>
                <div class="d-flex flex-wrap gap-2">
                    {% if search_query %}
                        <span class="badge bg-primary">Search: {{ search_query }}</span>
                    {% endif %}
                    {% if selected_family %}
                        <span class="badge bg-info">{{ selected_family.name }}</span>
                    {% endif %}
                    {% if selected_visibility %}
                        <span class="badge bg-warning">{{ selected_visibility }}</span>
                    {% endif %}
                    {% if selected_date_range %}
                        <span class="badge bg-success">{{ selected_date_range|title }}</span>
                    {% endif %}
                </div>
            </div>
            {% endif %}
        </aside>

        <!-- Mobile Filter Toggle -->
        <button class="filter-toggle-mobile" id="filterToggleMobile">
            <i class="bi bi-funnel"></i>
        </button>
        <div class="filter-overlay" id="filterOverlay"></div>

        <!-- Main Content Area -->
        <div class="events-main-content">
            <div class="row">
                <div class="col-lg-8">
                    <div class="card mb-4">
                        <div class="card-header">
                            <h4>Upcoming Events</h4>
                        </div>
                        <div class="card-body">
                            {% if upcoming_events %}
                                {% for event in upcoming_events %}
                                <div class="event-card p-3 {% if event.visibility == 'PERSONAL' %}personal{% elif event.visibility == 'PRIVATE' %}private{% endif %}" style="border-left-color: {{ event.display_color|default:'var(--primary)' }};">
                                    <div class="event-time">
                                        {% if event.is_all_day %}
                                            {{ event.start_time|date:"l, F j, Y" }} — All Day
                                        {% elif event.start_time.date == event.end_time.date %}
                                            {{ event.start_time|date:"l, F j, Y" }} from {{ event.start_time|date:"g:i A" }} to {{ event.end_time|date:"g:i A" }}
                                        {% else %}
                                            {{ event.start_time|date:"l, F j, Y g:i A" }} to {{ event.end_time|date:"l, F j, Y g:i A" }}
                                        {% endif %}
                                    </div>
                                    <div class="event-title">
                                        {% with calendar_info=event_calendar_info|get_item:event.id child_info=event_child_info|get_item:event.id %}
                                        {% if calendar_info and calendar_info.type == 'SPORTS' %}
                                            {% sport_icon_class calendar_info.sports_subcategory as icon_cls %}
                                            <i class="event-color-marker {{ icon_cls }}" style="color: {{ event.display_color|default:'var(--primary)' }};" title="{{ calendar_info.sports_subcategory }}"></i>
                                        {% else %}
                                            <span class="event-color-dot" style="background-color: {{ event.display_color|default:'var(--primary)' }};"></span>
                                        {% endif %}

                                        {% if calendar_info and calendar_info.associated_users %}
                                            {% with assoc_user=calendar_info.associated_users.0 %}
                                                <span class="event-owner" title="{{ assoc_user.name }}">
                                                    {% if assoc_user.avatar_url %}
                                                        <img src="{{ assoc_user.avatar_url }}" alt="{{ assoc_user.name }}" class="event-owner-avatar">
                                                    {% elif assoc_user.initials %}
                                                        <span class="event-owner-initials" style="background-color: {{ event.display_color|default:'var(--primary)' }};">
                                                            {{ assoc_user.initials }}
                                                        </span>
                                                    {% else %}
                                                        <span class="event-owner-initials" style="background-color: {{ event.display_color|default:'var(--primary)' }};">?</span>
                                                    {% endif %}
                                                    <span class="event-owner-name">{{ assoc_user.short_name|default:assoc_user.name }}</span>
                                                </span>
                                            {% endwith %}
                                        {% elif child_info %}
                                            <a href="{% url 'event_detail' event.id %}" class="child-event-display me-2" title="{{ event.title }}">
                                                <img src="{{ child_info.picture_url }}" alt="{{ child_info.name }}" class="child-event-img">
                                                <span class="child-event-name">{{ child_info.name }}</span>
                                            </a>
                                        {% endif %}
                                        <a href="{% url 'event_detail' event.id %}">{{ event.title }}</a>
                                        {% endwith %} {# End calendar_info with #}
                                    </div>
                                    {% if event.location %}
                                        <div class="event-location">
                                            <i class="bi bi-geo-alt"></i> {{ event.location }}
                                        </div>
                                    {% endif %}
                                    <div class="event-meta">
                                        <span class="badge {% if event.visibility == 'PUBLIC' %}bg-primary{% elif event.visibility == 'PRIVATE' %}bg-warning{% else %}bg-success{% endif %}">
                                            {{ event.get_visibility_display }}
                                        </span>

                                        {% if event.family_group %}
                                            <span class="badge bg-info">{{ event.family_group.name }}</span>
                                        {% endif %}

                                        {% for participant in event.participants.all %}
                                            {% if participant.user == request.user %}
                                                <span class="badge badge-rsvp-{{ participant.rsvp_status|lower }}">
                                                    {{ participant.get_rsvp_status_display }}
                                                </span>
                                            {% endif %}
                                        {% endfor %}
                                    </div>
                                    <div class="mt-2">
                                        <a href="{% url 'event_detail' event.id %}" class="btn btn-sm btn-outline-primary">View Details</a>

                                        {% if event.creator == request.user %}
                                            <a href="{% url 'event_edit' event.id %}" class="btn btn-sm btn-outline-secondary">Edit</a>
                                        {% endif %}
                                    </div>
                                </div>
                                {% endfor %}
                            {% else %}
                                <div class="no-events">
                                    <i class="bi bi-calendar-x"></i>
                                    <h4>No upcoming events</h4>
                                    <p>Create a new event to get started.</p>
                                    <a href="{% url 'event_create' %}" class="btn btn-primary">Create Event</a>
                                </div>
                            {% endif %}
                        </div>
                    </div>

                    <div class="card">
                        <div class="card-header d-flex justify-content-between align-items-center">
                            <h4>Past Events</h4>
                            <button class="btn btn-sm btn-link" type="button" data-bs-toggle="collapse" data-bs-target="#pastEventsCollapse" aria-expanded="false" aria-controls="pastEventsCollapse">
                                <i class="bi bi-chevron-down"></i>
                            </button>
                        </div>
                        <div class="collapse card-body" id="pastEventsCollapse">
                            {% if past_events %}
                                {% for event in past_events %}
                                <div class="event-card p-3 {% if event.visibility == 'PERSONAL' %}personal{% elif event.visibility == 'PRIVATE' %}private{% endif %}" style="border-left-color: {{ event.display_color|default:'var(--primary)' }};">
                                    <div class="event-time">
                                        {% if event.is_all_day %}
                                            {{ event.start_time|date:"l, F j, Y" }} — All Day
                                        {% elif event.start_time.date == event.end_time.date %}
                                            {{ event.start_time|date:"l, F j, Y" }} from {{ event.start_time|date:"g:i A" }} to {{ event.end_time|date:"g:i A" }}
                                        {% else %}
                                            {{ event.start_time|date:"l, F j, Y g:i A" }} to {{ event.end_time|date:"l, F j, Y g:i A" }}
                                        {% endif %}
                                    </div>
                                    <div class="event-title">
                                        {% with calendar_info=event_calendar_info|get_item:event.id child_info=event_child_info|get_item:event.id %}
                                        {% if calendar_info and calendar_info.type == 'SPORTS' %}
                                            {% sport_icon_class calendar_info.sports_subcategory as icon_cls %}
                                            <i class="event-color-marker {{ icon_cls }}" style="color: {{ event.display_color|default:'var(--primary)' }};" title="{{ calendar_info.sports_subcategory }}"></i>
                                        {% else %}
                                            <span class="event-color-dot" style="background-color: {{ event.display_color|default:'var(--primary)' }};"></span>
                                        {% endif %}

                                        {% if calendar_info and calendar_info.associated_users %}
                                            {% with assoc_user=calendar_info.associated_users.0 %}
                                                <span class="event-owner" title="{{ assoc_user.name }}">
                                                    {% if assoc_user.avatar_url %}
                                                        <img src="{{ assoc_user.avatar_url }}" alt="{{ assoc_user.name }}" class="event-owner-avatar">
                                                    {% elif assoc_user.initials %}
                                                        <span class="event-owner-initials" style="background-color: {{ event.display_color|default:'var(--primary)' }};">
                                                            {{ assoc_user.initials }}
                                                        </span>
                                                    {% else %}
                                                        <span class="event-owner-initials" style="background-color: {{ event.display_color|default:'var(--primary)' }};">?</span>
                                                    {% endif %}
                                                    <span class="event-owner-name">{{ assoc_user.short_name|default:assoc_user.name }}</span>
                                                </span>
                                            {% endwith %}
                                        {% elif child_info %}
                                            <a href="{% url 'event_detail' event.id %}" class="child-event-display me-2" title="{{ event.title }}">
                                                <img src="{{ child_info.picture_url }}" alt="{{ child_info.name }}" class="child-event-img">
                                                <span class="child-event-name">{{ child_info.name }}</span>
                                            </a>
                                        {% endif %}
                                        <a href="{% url 'event_detail' event.id %}">{{ event.title }}</a>
                                        {% endwith %} {# End calendar_info with #}
                                    </div>
                                    {% if event.location %}
                                        <div class="event-location">
                                            <i class="bi bi-geo-alt"></i> {{ event.location }}
                                        </div>
                                    {% endif %}
                                    <div class="event-meta">
                                        <span class="badge {% if event.visibility == 'PUBLIC' %}bg-primary{% elif event.visibility == 'PRIVATE' %}bg-warning{% else %}bg-success{% endif %}">
                                            {{ event.get_visibility_display }}
                                        </span>

                                        {% if event.family_group %}
                                            <span class="badge bg-info">{{ event.family_group.name }}</span>
                                        {% endif %}

                                        {% for participant in event.participants.all %}
                                            {% if participant.user == request.user %}
                                                <span class="badge badge-rsvp-{{ participant.rsvp_status|lower }}">
                                                    {{ participant.get_rsvp_status_display }}
                                                </span>
                                            {% endif %}
                                        {% endfor %}
                                    </div>
                                    <div class="mt-2">
                                        <a href="{% url 'event_detail' event.id %}" class="btn btn-sm btn-outline-primary">View Details</a>
                                    </div>
                                </div>
                                {% endfor %}
                            {% else %}
                                <p class="text-muted">No past events.</p>
                            {% endif %}
                        </div>
                    </div>
                </div>

                <div class="col-lg-4">
                    <div class="card mb-4">
                        <div class="card-header">
                            <h5>Quick Actions</h5>
                        </div>
                        <div class="card-body">
                            <div class="d-grid gap-2">
                                <a href="{% url 'event_create' %}" class="btn btn-primary text-truncate">
                                    <i class="bi bi-plus-circle me-1"></i>Create New Event
                                </a>
                                {% if family_features.clancy_available %}
                                <button type="button"
                                        class="btn btn-outline-primary text-truncate"
                                        data-clancy-open
                                        data-clancy-prompt="Help me add an event to our family calendar.">
                                    <i class="bi bi-stars me-1"></i>Quick Ask {{ family_features.helper_agent_name|default:"Clancy" }}
                                </button>
                                {% endif %}
                                <a href="{% url 'calendars:quick_connect' %}" class="btn btn-outline-success text-truncate">
                                    <i class="bi bi-calendar-plus me-1"></i>Quick Add Calendar
                                </a>
                                <a href="{% url 'event_bulk_select' %}" class="btn btn-outline-primary text-truncate" title="Select and edit multiple existing events">
                                    <i class="bi bi-pencil-square me-1"></i>Bulk Edit Existing Events
                                </a>
                                <a href="{% url 'csv_import' %}" class="btn btn-outline-info text-truncate" title="Import events from CSV file">
                                    <i class="bi bi-file-earmark-arrow-up me-1"></i>Import Events from CSV
                                </a>
                                <!-- <a href="{% url 'calendars:calendar' %}" class="btn btn-outline-primary">Calendar View</a>
                                <a href="{% url 'calendars:week_view' %}" class="btn btn-outline-primary">Week View</a>
                                <a href="{% url 'calendars:day_view_with_date' now.year now.month now.day %}" class="btn btn-outline-primary">Today's Events</a> -->
                            </div>
                        </div>
                    </div>

                    <div class="col-md-12">
                      <div class="card">
                          <div class="card-header">
                              <h5>My Calendars</h5>
                          </div>
                          <div class="card-body">
                              {% if external_calendars or internal_calendars %}
                                  <ul class="list-group">
                                      {% for calendar in external_calendars %}
                                      <li class="list-group-item d-flex justify-content-between align-items-center">
                                          <div>
                                              {% if calendar.type == 'SPORTS' %}
                                                  {% sport_icon_class calendar.sports_subcategory as icon_cls %}
                                                  <i class="{{ icon_cls }}" title="{{ calendar.sports_subcategory }}"></i>
                                              {% endif %}
                                              {{ calendar.account_name }} ({{ calendar.get_provider_display }})
                                          </div>
                                          <span class="badge {% if calendar.is_active %}bg-success{% else %}bg-secondary{% endif %} rounded-pill">
                                              {% if calendar.is_active %}Active{% else %}Inactive{% endif %}
                                          </span>
                                      </li>
                                      {% endfor %}

                                      {% for calendar in internal_calendars %}
                                      <li class="list-group-item d-flex justify-content-between align-items-center">
                                          <div>
                                              {% if calendar.type == 'SPORTS' %}
                                                  {% sport_icon_class calendar.sports_subcategory as icon_cls %}
                                                  <i class="{{ icon_cls }}" title="{{ calendar.sports_subcategory }}"></i>
                                              {% endif %}
                                              {{ calendar.name }}
                                          </div>
                                          <span class="badge {% if calendar.is_active %}bg-success{% else %}bg-secondary{% endif %} rounded-pill">
                                              {% if calendar.is_active %}Active{% else %}Inactive{% endif %}
                                          </span>
                                      </li>
                                      {% endfor %}
                                  </ul>
                                  <div class="mt-3">
                                      <a href="{% url 'calendars:calendar_list' %}" class="btn btn-outline-primary">Manage Calendars</a>
                                  </div>
                              {% else %}
                                  <p>No calendars configured.</p>
                                  <a href="{% url 'calendars:calendar_list' %}" class="btn btn-primary">Add Calendar</a>
                              {% endif %}
                          </div>
                      </div>
                  </div>
                </div>
            </div>
        </div>
    </div>
</div>
{% endblock %}

{% block extra_js %}
<script>
function initializeEventFilters() {
    // Get user identifier for localStorage namespacing
    const userId = '{{ request.user.id|default:"anonymous" }}';

    // Date range custom fields toggle
    const dateRangeSelect = document.getElementById('date_range');
    const customDateRangeFields = document.querySelectorAll('.custom-date-range');

    function toggleCustomDateRange() {
        if (!dateRangeSelect) return;
        const showCustom = dateRangeSelect.value === 'CUSTOM';
        customDateRangeFields.forEach(field => {
            field.style.display = showCustom ? 'block' : 'none';
        });
    }

    if (dateRangeSelect) {
        dateRangeSelect.addEventListener('change', toggleCustomDateRange);
        toggleCustomDateRange(); // Initial state
    }

    // Mobile filter sidebar toggle
    const filterToggleMobile = document.getElementById('filterToggleMobile');
    const filterSidebar = document.getElementById('filterSidebar');
    const filterOverlay = document.getElementById('filterOverlay');

    if (filterToggleMobile && filterSidebar && filterOverlay) {
        filterToggleMobile.addEventListener('click', function() {
            filterSidebar.classList.toggle('active');
            filterOverlay.classList.toggle('active');
        });

        filterOverlay.addEventListener('click', function() {
            filterSidebar.classList.remove('active');
            filterOverlay.classList.remove('active');
        });
    }

    // Count active filters and update badge
    function updateActiveFilterCount() {
        let activeCount = 0;
        const searchInput = document.getElementById('q');
        const familySelect = document.getElementById('family');
        const visibilitySelect = document.getElementById('visibility');
        const dateRangeSelect = document.getElementById('date_range');

        if (searchInput && searchInput.value) activeCount++;
        if (familySelect && familySelect.value) activeCount++;
        if (visibilitySelect && visibilitySelect.value) activeCount++;
        if (dateRangeSelect && dateRangeSelect.value) activeCount++;

        const badge = document.getElementById('activeFiltersCount');
        if (badge) {
            if (activeCount > 0) {
                badge.textContent = activeCount + ' Active';
                badge.style.display = 'inline-block';
            } else {
                badge.style.display = 'none';
            }
        }

        // Update mobile button badge
        if (filterToggleMobile && activeCount > 0) {
            filterToggleMobile.innerHTML = '<i class="bi bi-funnel-fill"></i>';
            filterToggleMobile.style.background = 'var(--warning)';
        } else if (filterToggleMobile) {
            filterToggleMobile.innerHTML = '<i class="bi bi-funnel"></i>';
            filterToggleMobile.style.background = 'var(--primary)';
        }
    }

    // Update count on page load
    updateActiveFilterCount();

    // Filter persistence with localStorage (namespaced per user)
    const FILTER_STORAGE_KEY = `eventListFilters_${userId}`;

    // Save filter state to localStorage
    function saveFilterState() {
        try {
            const searchInput = document.getElementById('q');
            const familySelect = document.getElementById('family');
            const visibilitySelect = document.getElementById('visibility');
            const dateRangeSelect = document.getElementById('date_range');
            const monthSelect = document.getElementById('month');
            const yearSelect = document.getElementById('year');

            const filterState = {
                search: searchInput ? searchInput.value : '',
                family: familySelect ? familySelect.value : '',
                visibility: visibilitySelect ? visibilitySelect.value : '',
                dateRange: dateRangeSelect ? dateRangeSelect.value : '',
                month: monthSelect ? monthSelect.value : '',
                year: yearSelect ? yearSelect.value : '',
                timestamp: Date.now()
            };
            localStorage.setItem(FILTER_STORAGE_KEY, JSON.stringify(filterState));
        } catch (e) {
            console.error('Error saving filter state:', e);
        }
    }

    // Load filter state from localStorage (only if no filters in URL)
    function loadFilterState() {
        try {
            // Check if there are any filters in the URL
            const urlParams = new URLSearchParams(window.location.search);
            const hasUrlFilters = urlParams.get('q') || urlParams.get('family') ||
                                 urlParams.get('visibility') || urlParams.get('date_range');

            if (!hasUrlFilters) {
                const savedState = localStorage.getItem(FILTER_STORAGE_KEY);
                if (savedState) {
                    const filterState = JSON.parse(savedState);

                    // Only restore if saved within last 24 hours
                    const dayInMs = 24 * 60 * 60 * 1000;
                    if (Date.now() - filterState.timestamp < dayInMs) {
                        // Ask user if they want to restore filters
                        const filterSummary = [];
                        if (filterState.search) filterSummary.push('Search: ' + filterState.search);
                        if (filterState.family) filterSummary.push('Family filter');
                        if (filterState.visibility) filterSummary.push('Visibility filter');
                        if (filterState.dateRange) filterSummary.push('Date filter');

                        if (filterSummary.length > 0) {
                            // Create a subtle notification instead of confirm dialog
                            const restoreBar = document.createElement('div');
                            restoreBar.className = 'alert alert-info alert-dismissible fade show mb-3';
                            restoreBar.innerHTML = `
                                <i class="bi bi-info-circle me-2"></i>
                                <strong>Previous filters detected:</strong> ${filterSummary.join(', ')}
                                <button type="button" class="btn btn-sm btn-primary ms-3" id="restoreFilters">
                                    <i class="bi bi-arrow-clockwise me-1"></i>Restore
                                </button>
                                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
                            `;

                            const mainContent = document.querySelector('.events-main-content');
                            if (mainContent) {
                                mainContent.insertBefore(restoreBar, mainContent.firstChild);

                                document.getElementById('restoreFilters')?.addEventListener('click', function() {
                                    // Restore filter values with null checks
                                    const searchInput = document.getElementById('q');
                                    const familySelect = document.getElementById('family');
                                    const visibilitySelect = document.getElementById('visibility');
                                    const dateRangeSelect = document.getElementById('date_range');
                                    const monthSelect = document.getElementById('month');
                                    const yearSelect = document.getElementById('year');
                                    const filterForm = document.getElementById('filterForm');

                                    if (filterState.search && searchInput) searchInput.value = filterState.search;
                                    if (filterState.family && familySelect) familySelect.value = filterState.family;
                                    if (filterState.visibility && visibilitySelect) visibilitySelect.value = filterState.visibility;
                                    if (filterState.dateRange && dateRangeSelect) {
                                        dateRangeSelect.value = filterState.dateRange;
                                        toggleCustomDateRange();
                                    }
                                    if (filterState.month && monthSelect) monthSelect.value = filterState.month;
                                    if (filterState.year && yearSelect) yearSelect.value = filterState.year;

                                    // Submit the form if it exists
                                    if (filterForm) {
                                        filterForm.submit();
                                    }
                                });
                            }
                        }
                    }
                }
            }
        } catch (e) {
            console.error('Error loading filter state:', e);
        }
    }

    // Save filters when they change
    const filterInputs = document.querySelectorAll('#filterForm select, #filterForm input');
    filterInputs.forEach(input => {
        input.addEventListener('change', saveFilterState);
    });

    // Clear saved filters when Clear All is clicked
    const clearButton = document.querySelector('.clear-filters-btn');
    if (clearButton) {
        clearButton.addEventListener('click', function() {
            localStorage.removeItem(FILTER_STORAGE_KEY);
        });
    }

    // Load filter state on page load
    loadFilterState();

    // Auto-submit filters on change (optional - commented out for now)
    // const filterForm = document.getElementById('filterForm');
    // filterInputs.forEach(input => {
    //     input.addEventListener('change', function() {
    //         saveFilterState();
    //         filterForm.submit();
    //     });
    // });
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeEventFilters);
} else {
    initializeEventFilters();
}
</script>
