"""
Context processors for the family_scheduler project.

This module defines context processors that add variables to the template context.
"""

import logging
from typing import Any

from django.conf import settings
from django.db.models import Q

logger = logging.getLogger(__name__)


def google_places_api_key(request: Any) -> dict[str, Any]:
    """
    Add the Google Places API key to the template context.

    Args:
        request: The HTTP request

    Returns:
        dict: A dictionary containing the Google Places API key
    """
    return {"google_places_api_key": settings.GOOGLE_PLACES_API_KEY}


def pending_invitations_count(request: Any) -> dict[str, Any]:
    """
    Add the count of pending invitations for the current user to the context.

    Args:
        request: The HTTP request

    Returns:
        dict: A dictionary containing the pending invitation count
    """
    if not request.user.is_authenticated:
        return {"pending_invitations_count": 0}

    from users.models import FamilyInvite

    # Safely get user email
    user_email = getattr(request.user, "email", None)
    if not user_email:
        return {"pending_invitations_count": 0}

    # Count invites sent to user's email
    invite_count = FamilyInvite.objects.filter(
        email=user_email, status="PENDING"
    ).count()

    # Count network invites if user has a primary family
    # Safely access profile to avoid RelatedObjectDoesNotExist
    profile = getattr(request.user, "profile", None)
    primary_family = getattr(profile, "primary_family", None) if profile else None

    if primary_family:
        try:
            network_invite_count = FamilyInvite.objects.filter(
                Q(create_meta_group=True) | Q(existing_meta_group__isnull=False),
                family=primary_family,
                status="PENDING",
            ).count()
            invite_count += network_invite_count
        except Exception as e:
            # If the database fields don't exist yet (migrations pending),
            # gracefully skip network invites count
            logger.debug(
                "Unable to count network invites, likely due to pending migrations: %s",
                str(e),
            )

    return {"pending_invitations_count": invite_count}


def frames_navigation(request: Any) -> dict[str, Any]:
    """Expose frame feature rollout state for templates."""

    if not request.user.is_authenticated:
        return {
            "frames_feature_enabled": False,
            "frames_admin_access": False,
        }

    try:
        from frames.feature_flags import frames_feature_flags
        from users.utils import get_user_admin_families
    except Exception:  # pragma: no cover - defensive import guard
        return {
            "frames_feature_enabled": False,
            "frames_admin_access": False,
        }

    frames_enabled = frames_feature_flags.is_enabled(request.user)
    if not frames_enabled:
        return {
            "frames_feature_enabled": False,
            "frames_admin_access": False,
        }

    has_admin_family = get_user_admin_families(request.user).exists()
    return {
        "frames_feature_enabled": frames_enabled,
        "frames_admin_access": has_admin_family,
    }


def _build_clancy_assistant_context(
    request: Any, family_features: dict[str, Any]
) -> tuple[dict[str, Any], str]:
    context: dict[str, Any] = {
        "source_screen": "web_page",
        "family_id": family_features.get("family_id") or None,
        "path": getattr(request, "path", ""),
    }
    prompt = "Help me with this page."
    resolver_match = getattr(request, "resolver_match", None)
    route_name = getattr(resolver_match, "url_name", "") or ""
    namespace = getattr(resolver_match, "namespace", "") or ""
    route_kwargs = getattr(resolver_match, "kwargs", {}) or {}

    if route_name == "event_list":
        context["source_screen"] = "event_list"
        prompt = "Help me add an event to our family calendar."
        event_filters = {
            key: request.GET.get(key)
            for key in (
                "q",
                "family",
                "visibility",
                "calendar_type",
                "date_range",
                "participant",
            )
            if request.GET.get(key)
        }
        if event_filters:
            context["event_filters"] = event_filters
    elif route_name == "event_detail":
        context["source_screen"] = "event_detail"
        if route_kwargs.get("event_id"):
            context["event_id"] = str(route_kwargs["event_id"])
        prompt = "Help me plan around this event."
    elif namespace == "trips" and route_name == "trip_detail":
        context["source_screen"] = "trip_detail"
        if route_kwargs.get("pk"):
            context["trip_id"] = str(route_kwargs["pk"])
        prompt = "Help me plan for this trip."
    elif route_name == "dashboard":
        context["source_screen"] = "dashboard"
        context["today_section"] = "overview"
        prompt = "What should our family pay attention to today?"

    return context, prompt


def family_feature_settings(request: Any) -> dict[str, Any]:
    """Expose family feature settings to templates for conditional nav rendering."""
    defaults = {
        "family_features": {
            "trips_enabled": True,
            "organize_enabled": True,
            "households_enabled": True,
            "groceries_enabled": True,
            "recipes_enabled": True,
            "meals_enabled": True,
            "agent_enabled": False,
            "clancy_available": False,
            "helper_agent_name": "Clancy",
            "family_id": "",
        },
        "clancy_assistant_context": {
            "source_screen": "web_page",
            "family_id": None,
            "path": getattr(request, "path", ""),
        },
        "clancy_assistant_prompt": "Help me with this page.",
    }

    if not request.user.is_authenticated:
        return defaults

    cache_attr = "_family_feature_settings"
    if hasattr(request, cache_attr):
        features = getattr(request, cache_attr)
        context, prompt = _build_clancy_assistant_context(request, features)
        return {
            "family_features": features,
            "clancy_assistant_context": context,
            "clancy_assistant_prompt": prompt,
        }

    try:
        from family_agent.feature_flags import family_planner_feature_flags
        from users.feature_gate import _get_user_primary_family_settings
        from users.models import (
            DEFAULT_FAMILY_HELPER_AGENT_NAME,
            FamilyGroup,
            FamilyMembership,
        )
        from users.utils import get_user_immediate_family
    except Exception:
        return defaults

    settings_obj = _get_user_primary_family_settings(request.user)
    if not settings_obj:
        return defaults

    features = {
        "trips_enabled": settings_obj.trips_enabled,
        "organize_enabled": settings_obj.organize_enabled,
        "households_enabled": settings_obj.households_enabled,
        "groceries_enabled": settings_obj.groceries_enabled,
        "recipes_enabled": settings_obj.recipes_enabled,
        "meals_enabled": settings_obj.meals_enabled,
        "agent_enabled": settings_obj.agent_enabled,
        "clancy_available": False,
        "helper_agent_name": (
            (settings_obj.family.helper_agent_name or "").strip()
            or DEFAULT_FAMILY_HELPER_AGENT_NAME
        ),
        "family_id": str(settings_obj.family_id),
    }

    try:
        immediate_family = get_user_immediate_family(request.user)
        if immediate_family is not None:
            immediate_family = FamilyGroup.objects.select_related(
                "feature_settings"
            ).get(id=immediate_family.id)
            is_admin = FamilyMembership.objects.filter(
                user=request.user,
                family=immediate_family,
                is_active=True,
                is_admin=True,
            ).exists()
            features["clancy_available"] = bool(
                family_planner_feature_flags.is_enabled(request.user)
                and immediate_family.feature_settings.agent_enabled
                and (is_admin or request.user.is_staff)
            )
            features["agent_enabled"] = immediate_family.feature_settings.agent_enabled
            features["helper_agent_name"] = (
                immediate_family.helper_agent_name or ""
            ).strip() or DEFAULT_FAMILY_HELPER_AGENT_NAME
            features["family_id"] = str(immediate_family.id)
    except Exception:
        logger.debug("Unable to resolve Clancy navigation state", exc_info=True)

    setattr(request, cache_attr, features)
    context, prompt = _build_clancy_assistant_context(request, features)
    return {
        "family_features": features,
        "clancy_assistant_context": context,
        "clancy_assistant_prompt": prompt,
    }


def billing_navigation(request: Any) -> dict[str, Any]:
    """Expose billing nav visibility for templates.

    Only users who are admin in at least one family should see billing.
    Uses per-request caching to avoid repeated DB queries.
    """
    if not request.user.is_authenticated:
        return {"show_billing_nav": False}

    cache_attr = "_billing_nav_is_admin"
    if hasattr(request, cache_attr):
        return {"show_billing_nav": getattr(request, cache_attr)}

    try:
        from users.utils import get_user_admin_families
    except Exception:  # pragma: no cover - defensive import guard
        return {"show_billing_nav": False}

    result = get_user_admin_families(request.user).exists()
    setattr(request, cache_attr, result)
    return {"show_billing_nav": result}

