"""DRF serializers for planner tool-request arguments.

The planner LLM emits ``tool_request`` JSON payloads whose ``arguments`` object
must be shaped to match an adapter method on :class:`FamilyPlannerToolAdapter`.
These serializers run *before* adapter dispatch in
``HermesFamilyPlannerRuntime._execute_tool_request`` so that malformed tool
arguments (missing required fields, bad enum values, invented kwargs) surface
as recoverable tool errors that the runtime can feed back to the model — not
uncaught ``TypeError``s that crash the Celery task.

These are intentionally separate from the external API serializers in
``family_agent.serializers``. The mobile request contract is already
validated at the DRF view boundary; these schemas govern the *internal*
LLM → adapter contract.
"""

from __future__ import annotations

from typing import Any

from rest_framework import serializers

CALENDAR_SCOPES = ("immediate_family", "network_public")


class _UnknownFieldsMixin:
    """Reject unknown keys so invented tool args surface immediately."""

    def to_internal_value(self, data: Any) -> Any:
        if isinstance(data, dict):
            declared = set(self.fields)  # type: ignore[attr-defined]
            unknown = [key for key in data.keys() if key not in declared]
            if unknown:
                raise serializers.ValidationError(
                    dict.fromkeys(unknown, "Unknown field.")
                )
        return super().to_internal_value(data)  # type: ignore[misc]


def _invalid(message: str) -> serializers.ValidationError:
    return serializers.ValidationError(message)


class _StringOrListField(serializers.Field[Any, Any, Any, Any]):
    """Accept a single string or a list of strings; normalize to a list."""

    def to_internal_value(self, data: Any) -> list[str]:
        if isinstance(data, str):
            return [data]
        if isinstance(data, (list, tuple)):
            result: list[str] = []
            for item in data:
                if not isinstance(item, str):
                    raise _invalid("Must be a string or a list of strings.")
                result.append(item)
            return result
        raise _invalid("Must be a string or a list of strings.")

    def to_representation(self, value: Any) -> Any:
        return value


class _IntOrIntListField(serializers.Field[Any, Any, Any, Any]):
    """Accept an int or a list of ints; normalize to a list of ints."""

    def to_internal_value(self, data: Any) -> list[int]:
        if isinstance(data, bool):
            raise _invalid("Must be an integer or a list of integers.")
        if isinstance(data, int):
            return [data]
        if isinstance(data, (list, tuple)):
            result: list[int] = []
            for item in data:
                if isinstance(item, bool) or not isinstance(item, int):
                    raise _invalid("Must be an integer or a list of integers.")
                result.append(item)
            return result
        raise _invalid("Must be an integer or a list of integers.")

    def to_representation(self, value: Any) -> Any:
        return value


