    currency = serializers.CharField(required=False, allow_null=True)
    intent = serializers.CharField(required=False, allow_null=True)
    limit = serializers.IntegerField(required=False)
    cursor = serializers.CharField(required=False, allow_null=True)

    def validate(self, attrs: dict[str, Any]) -> dict[str, Any]:
        normalized_query = str(attrs.get("query") or "").strip()
        normalized_cursor = str(attrs.get("cursor") or "").strip()
        has_filters = bool(attrs.get("categories")) or any(
            attrs.get(key) is not None for key in ("min_price_minor", "max_price_minor")
        )
        if not normalized_query and not normalized_cursor and not has_filters:
            raise serializers.ValidationError(
                "Provide a query, filters, or a pagination cursor."
