    response = serializers.ChoiceField(
        choices=("YES", "MAYBE", "NO"),
        required=False,
    )
    clear = serializers.BooleanField(required=False, default=False)
    note = serializers.CharField(required=False, allow_blank=True, max_length=255)

    def validate(self, attrs: dict[str, Any]) -> dict[str, Any]:
        if not any(
            attrs.get(field_name)
            for field_name in ("plan_option_id", "start_time", "date")
        ):
            raise serializers.ValidationError(
                "Provide at least one of plan_option_id, start_time, or date."
            )

        clear = attrs.get("clear", False)
        response = attrs.get("response")
        if clear and response is not None:
            raise serializers.ValidationError(
                {"response": "Do not provide response when clear is true."}
            )
        if not clear and response is None:
            raise serializers.ValidationError(
                {"response": "This field is required unless clear is true."}
            )
        return attrs


