# Registry: tool_name -> (adapter method name, args serializer class).
TOOL_REQUEST_REGISTRY: dict[str, tuple[str, type[serializers.Serializer[Any]]]] = {
    "query_calendar_day": ("query_calendar_day", QueryCalendarDayArgs),
    "query_calendar_blocks": ("query_calendar_blocks", QueryCalendarBlocksArgs),
    "check_time_blocked": ("check_time_blocked", CheckTimeBlockedArgs),
    "get_event_details": ("get_event_details", GetEventDetailsArgs),
