        PrepareSchedulingBookingArgs,
    ),
}


def _field_entry(
    name: str, field: serializers.Field[Any, Any, Any, Any]
) -> dict[str, Any]:
    entry: dict[str, Any] = {"name": name}
    if isinstance(field, serializers.ChoiceField):
        entry["enum"] = list(field.choices.keys())
    return entry


def describe_tool_contracts() -> list[dict[str, Any]]:
    """Registry-derived contract docs for prompt + context injection."""

    contracts: list[dict[str, Any]] = []
    for tool_name, entry in TOOL_REQUEST_REGISTRY.items():
        serializer_cls = entry[1]
        serializer = serializer_cls()
        required: list[dict[str, Any]] = []
        optional: list[dict[str, Any]] = []
        for field_name, field in serializer.fields.items():
            bucket = required if field.required else optional
            bucket.append(_field_entry(field_name, field))
        contracts.append(
            {
                "name": tool_name,
                "required": required,
                "optional": optional,
            }
        )
    return contracts

