          json: { title: 'New conversation' },
        });
        state.activeThreadId = thread.id;
      }

      const formData = new FormData();
      formData.append('thread_id', state.activeThreadId);
      formData.append('text', text);
      formData.append('context', JSON.stringify(buildMessageContext()));
      state.selectedFiles.forEach((file) => formData.append('images', file));

      const response = await apiRequest('/api/family-agent/thread/messages/', {
        method: 'POST',
        body: formData,
      });

      if (elements.input) {
        elements.input.value = '';
      }
      if (elements.imageInput) {
        elements.imageInput.value = '';
      }
      state.selectedFiles = [];
      state.pendingContext = {};
      renderSelectedImages();
      resizeComposer();
      await loadThreads(response?.thread?.id || state.activeThreadId);
