  function renderMessage(message) {
    const wrapper = document.createElement('article');
    wrapper.className = `clancy-message ${message.role || 'assistant'}`;

    const meta = document.createElement('div');
    meta.className = 'clancy-message-meta';
    meta.textContent = message.role === 'user' ? 'You' : helperName;

    const bubble = document.createElement('div');
    bubble.className = 'clancy-bubble';
    const text = document.createElement('div');
    text.className = 'clancy-message-text';
    if (message.role === 'assistant' || message.role === 'system') {
      renderFormattedMessageText(text, message.text || '');
    } else {
      text.textContent = message.text || '';
    }
    bubble.appendChild(text);

    wrapper.append(meta, bubble);
